#include <cuda_runtime.h>
#include "../bm3d-cuda/bm3d.hpp"
#include <chrono>
#include <cstdio>
#include <fstream>
#include <string>
#include <cmath>
#include <type_traits>
constexpr int W=112,H=40,G=64*12,R=10;
template<class T>T sentinel(){if constexpr(std::is_same<T,float>::value)return 1515.25f;else if constexpr(std::is_same<T,unsigned char>::value)return 165;else if constexpr(std::is_same<T,unsigned short>::value)return 23063;else return 1234567;}
template<class T>std::vector<T>read(const char*n,int count){std::vector<T>a(count);std::ifstream f(n,std::ios::binary);f.read((char*)a.data(),count*sizeof(T));if(!f)throw std::runtime_error(n);return a;}
template<class T>struct Buf{T*base,*v;int n;Buf(int size):n(size){cudaMalloc(&base,(n+32)*sizeof(T));v=base+16;std::vector<T>a(n+32,sentinel<T>());cudaMemcpy(base,a.data(),a.size()*sizeof(T),cudaMemcpyHostToDevice);}void put(std::vector<T>h){cudaMemcpy(v,h.data(),n*sizeof(T),cudaMemcpyHostToDevice);}void zero(){cudaMemset(v,0,n*sizeof(T));}std::vector<T>get(){std::vector<T>a(n);cudaMemcpy(a.data(),v,n*sizeof(T),cudaMemcpyDeviceToHost);return a;}bool guards(std::vector<float>&o){std::vector<T>a(n+32);cudaMemcpy(a.data(),base,a.size()*sizeof(T),cudaMemcpyDeviceToHost);bool ok=true;for(int j=0;j<16;j++){o.push_back(float(a[j]));o.push_back(float(a[n+16+j]));ok&=a[j]==sentinel<T>()&&a[n+16+j]==sentinel<T>();}return ok;}~Buf(){cudaFree(base);}};
int main(){auto input=read<unsigned char>("study_input_u8.bin",W*H);auto window=read<float>("study_window_f32.bin",64);auto es=read<unsigned short>("oracle_stacks_u16.bin",G*15);auto ec=read<unsigned int>("oracle_counts_u32.bin",G);auto enon=read<unsigned int>("oracle_nonzero_u32.bin",G);auto ew=read<float>("oracle_weights_f32.bin",G);auto ep=read<float>("oracle_post_f32.bin",G*1024);auto enumr=read<float>("oracle_num_f32.bin",W*H);auto ed=read<float>("oracle_den_f32.bin",W*H);auto eo=read<unsigned char>("oracle_output_u8.bin",W*H);
Buf<unsigned char>img(W*H),out(W*H);Buf<unsigned short>stacks(G*15);Buf<unsigned int>counts(G);Buf<float>group(G*1024),weights(G),win(64),num(W*H),den(W*H);img.put(input);win.put(window);Params params(19,8,16,2500,3,2.7f);uint2 dims=make_uint2(W,H),sdims=make_uint2(W-7,H-7),start=make_uint2(0,0);auto reset=[&](){stacks.zero();counts.zero();group.zero();weights.zero();out.zero();};
auto run=[&](){num.zero();den.zero();run_block_matching(img.v,stacks.v,counts.v,dims,sdims,params,start,dim3(512),dim3(2,12),38504);run_get_block(start,img.v,stacks.v,counts.v,group.v,dims,sdims,params,dim3(8,8),dim3(64,12));run_DCT2D8x8(group.v,group.v,G*1024,dim3(8,16),dim3(G));run_hard_treshold_block(start,group.v,weights.v,counts.v,sdims,params,625,dim3(8,8),dim3(64,12),4352);run_IDCT2D8x8(group.v,group.v,G*1024,dim3(8,16),dim3(G));run_aggregate_block(start,group.v,weights.v,stacks.v,win.v,num.v,den.v,counts.v,dims,sdims,params,dim3(8,8),dim3(64,12));run_aggregate_final(num.v,den.v,dims,out.v,dim3(64,4),dim3(2,10));};reset();run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;bool all=true;
for(int tr=1;tr<=5;tr++){reset();cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int j=0;j<R;j++)run();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/R;auto ai=img.get();auto ak=win.get();auto as=stacks.get();auto ac=counts.get();auto aw=weights.get();auto ap=group.get();auto an=num.get();auto ad=den.get();auto ao=out.get();bool ok=status==cudaSuccess&&ai==input&&ak==window&&as==es&&ac==ec;double ma=0,mr=0,scaled=0;int image_error=0,nzerror=0;auto check=[&](auto&a,auto&e){for(size_t i=0;i<a.size();i++){double err=fabs(double(a[i])-double(e[i]));ma=std::max(ma,err);mr=std::max(mr,err/std::max(fabs(double(e[i])),1.0));scaled=std::max(scaled,err/(.003+.0003*fabs(double(e[i]))));ok&=std::isfinite(a[i])&&err<=.003+.0003*fabs(double(e[i]));}};check(ap,ep);check(an,enumr);check(ad,ed);for(int j=0;j<G;j++){int nz=aw[j]>0?int(lrintf(1/aw[j])):0;nzerror+=nz!=int(enon[j]);ok&=nz==int(enon[j]);}for(int j=0;j<W*H;j++){image_error=std::max(image_error,abs(int(ao[j])-int(eo[j])));ok&=ad[j]>0;}ok&=image_error<=1;std::vector<float>a;auto append=[&](auto&v){for(auto z:v)a.push_back(float(z));};append(ai);append(ak);float par[]={W,H,64,12,19,8,16,3,625,2.7f,2500,R};a.insert(a.end(),par,par+12);append(as);append(ac);append(aw);append(ap);append(an);append(ad);append(ao);ok&=img.guards(a);ok&=win.guards(a);ok&=stacks.guards(a);ok&=counts.guards(a);ok&=weights.guards(a);ok&=group.guards(a);ok&=num.guards(a);ok&=den.guards(a);ok&=out.guards(a);all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(tr)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)a.data(),a.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"relative_error_floor\":1,\"max_scaled_oracle_error\":%.12g,\"image_max_gray_error\":%d,\"nonzero_count_mismatches\":%d,\"exact_stacks\":%s,\"exact_counts\":%s,\"timing_region\":\"full_BM3D_hardthreshold_pipeline_with_aggregation_resets_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",tr,seconds,ok?"true":"false",a.size(),ma,mr,scaled,image_error,nzerror,as==es?"true":"false",ac==ec?"true":"false",path.c_str(),a.size());}puts(all?"PASS":"FAIL");return all?0:1;}
